"""Build an offline, self-contained private review of measured native-loader samples."""
from pathlib import Path
import json,base64,argparse
parser=argparse.ArgumentParser();parser.add_argument('--root',type=Path,required=True);p=parser.parse_args().root
rows=[json.loads(s) for s in (p/'samples.jsonl').read_text().splitlines()]
pred={r['number']:r for r in map(json.loads,(p/'luna-results-v2.jsonl').read_text().splitlines())}
summary=json.loads((p/'luna-summary-v2.json').read_text());chosen=json.loads((p/'chosen-episode.json').read_text())
# Embed current images and each actual high-level history window. A file shared by samples is encoded only once.
paths={v for row in rows for v in row['current_images'].values()}
paths.update(v for row in rows for f in row['video_frames'] for v in f['images'].values())
images={s:'data:image/jpeg;base64,'+base64.b64encode((p/s).read_bytes()).decode() for s in paths}
for r in rows:r['luna']=pred[r['number']]
data=json.dumps({'rows':rows,'summary':summary,'chosen':chosen,'images':images},ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>长记忆 · 100 帧逐帧审阅</title><style>
:root{font-family:system-ui,sans-serif;color:#203042;background:#f3f6fa}*{box-sizing:border-box}body{margin:0}header{padding:28px max(20px,4vw);background:#112d40;color:white}h1{font-size:27px;margin:8px 0}small{opacity:.75}main{padding:20px max(16px,4vw)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.metric,section{background:white;border:1px solid #d9e2eb;border-radius:12px;padding:16px}.metric strong{display:block;font-size:25px;color:#126d82}.note{color:#52687a;line-height:1.7}nav{position:sticky;top:0;background:#f3f6faf5;display:flex;align-items:center;gap:12px;padding:12px 0;z-index:2}select,button,input{font:inherit}button,select{padding:9px;border-radius:7px;border:1px solid #c6d3df;background:white;color:#203042}button{cursor:pointer}input{flex:1;min-width:30px}.images{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}figure{margin:0}figure img{width:100%;border-radius:6px}figcaption{font-size:12px;color:#52687a}.columns{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}h2{font-size:20px;margin:0 0 10px}h3{font-size:15px}.entry{font-size:14px;line-height:1.6;padding:10px;background:#f3f6fa;border-radius:7px;margin-bottom:8px;overflow-wrap:anywhere}.entry b{display:block;color:#166178}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.tag{display:inline-block;padding:4px 9px;border-radius:15px;background:#e0f3ed;color:#256c53;font-size:13px}.bad{background:#fff0dc;color:#914d0f}.strip{display:flex;gap:8px;overflow-x:auto}.strip figure{min-width:180px;width:180px}.strip img{width:180px}details{margin-top:16px}summary{cursor:pointer;padding:10px}#index{min-width:86px}#source{overflow-wrap:anywhere}@media(max-width:750px){.metrics{grid-template-columns:repeat(2,1fr)}.columns{grid-template-columns:1fr}.images{grid-template-columns:1fr}header{padding:20px}h1{font-size:23px}}
</style><header><small>OPENPI / LONG MEMORY / NATIVE DATALOADER</small><h1>100 帧逐帧审阅</h1><div id="source"></div></header><main><div class="metrics"><div class="metric">动作阶段<strong>73 / 100</strong></div><div class="metric">有明确标签的瓶盖状态<strong>58 / 65</strong></div><div class="metric">瓶身持握手（诊断项）<strong>34 / 86</strong></div><div class="metric">100 次 API 成本<strong>$0.05219</strong></div></div><p class="note">随机选取一个 EP，再不放回随机抽取 100 帧，按时间排序。图片、训练记忆和 prompt 均来自真实原生 DataLoader。GPT 只看到过去三秒的视频帧与自己的前次记忆；人工标注没有发给 GPT。单个 EP 中的帧高度相关，这些分项准确率不能当作整体长记忆准确率。此次 100 帧审计的调用间隔随抽样时间变化，用于诊断，不是固定三秒闭环控制测试。</p><nav><button id="prev">←</button><span id="index"></span><input type="range" min="0" max="99" value="0" id="slider"><button id="next">→</button><select id="filter"><option value="all">全部帧</option><option value="wrong">阶段不一致</option><option value="home">回到初始位置</option></select></nav><section><h2 id="title"></h2><div id="tags"></div><div class="images" id="current"></div><div class="columns"><div><h3>人工标注 / 完整长记忆</h3><div id="truth"></div></div><div><h3>实际训练输入（含 dropout / 延迟）</h3><div id="train"></div></div><div><h3>GPT‑6 Luna 原始预测</h3><div id="prediction"></div></div></div><details><summary>过去三秒：实际输入视频帧（切换视角）</summary><select id="camera"><option>cam_high</option><option>cam_left_wrist</option><option>cam_right_wrist</option></select><div id="history" class="strip"></div></details><details><summary>实际 tokenizer 解码后的 low-level prompt</summary><pre id="prompt"></pre></details><details><summary>本帧完整数据与 API 计费 / 延迟</summary><pre id="raw"></pre></details></section><details><summary>GPT 的完整系统提示词与测试说明</summary><pre id="system"></pre></details><p class="note">回到初始位置：第 96 个样本确认周期完成并输出空记忆；第 97–99 个样本又生成了停放状态。这里保留原始预测，没有修饰结果。后续在线控制器已增加“等待下一瓶”门控，阻止 unknown / return_home 阶段重新填入旧记忆；这不是重跑后的 100 帧成绩。</p></main><script type="application/json" id="data">PAYLOAD</script><script>
const d=JSON.parse(document.getElementById('data').textContent);let i=0;const $=x=>document.getElementById(x);function txt(id,s){$(id).textContent=s}function entries(id,events){const dest=$(id);dest.replaceChildren();if(!events.length){const n=document.createElement('div');n.className='entry';n.textContent='空记忆';dest.append(n)}for(const e of events){const n=document.createElement('div');n.className='entry';const b=document.createElement('b');b.textContent=e.time_s.toFixed(3)+' s · '+e.bottle;n.append(b,document.createTextNode(e.observation+' → '+e.intent));dest.append(n)}}function figure(path,label){const f=document.createElement('figure'),im=document.createElement('img'),c=document.createElement('figcaption');im.src=d.images[path];im.alt=label;c.textContent=label;f.append(im,c);return f}function history(){const r=d.rows[i],dest=$('history');dest.replaceChildren();for(const f of r.video_frames)dest.append(figure(f.images[$('camera').value],f.time_s.toFixed(3)+' s'))}function show(){const r=d.rows[i],p=r.luna;txt('index',(i+1)+' / 100');$('slider').value=i;txt('title','Frame '+r.frame_index+' · '+r.time_s.toFixed(3)+' s');$('tags').replaceChildren();for(const s of [p.expected_phase+' → '+p.prediction.current_phase,p.latency_seconds.toFixed(2)+' 秒','$'+p.cost_usd.toFixed(6),p.prediction.cycle_complete?'周期结束 / 清空':'周期未结束']){const n=document.createElement('span');n.className='tag'+(p.phase_correct?'':' bad');n.textContent=s;$('tags').append(n,document.createTextNode(' '))}$('current').replaceChildren(...Object.entries(r.current_images).map(([c,path])=>figure(path,c)));entries('truth',r.full_annotation_memory.events);entries('train',r.actual_training_memory.events);entries('prediction',p.prediction.events);txt('prompt',r.model_prompt);txt('raw',JSON.stringify({...r,current_images:undefined,video_frames:r.video_frames.map(f=>({time_s:f.time_s}))},null,2));history()}function allowed(j){let v=$('filter').value;return v==='all'||v==='wrong'&&!d.rows[j].luna.phase_correct||v==='home'&&d.rows[j].luna.expected_phase==='return_home'}function move(delta){for(let j=i+delta;j>=0&&j<100;j+=delta)if(allowed(j)){i=j;show();break}}$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);$('slider').oninput=e=>{i=+e.target.value;show()};$('filter').onchange=()=>{if(!allowed(i)){i=d.rows.findIndex((_,j)=>allowed(j));show()}};$('camera').onchange=history;document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)});txt('source',d.chosen.repo_id+' · EP '+d.chosen.episode_index+' · seed '+d.chosen.seed);txt('system',d.summary.system_prompt);show();
</script></html>'''.replace('PAYLOAD',data)
(p/'review.html').write_text(page)
print('Written',p/'review.html',len(page)/1e6,'MB')
